```cypher
MATCH p=(s:Set {set_num:'41319-1'})-[e:CONTAINS*1..20]->(part:Part)
WITH p, e, nodes(p) AS ns, rels(e) AS rs
WITH p, e, ns, rs, range(0, size(rs)-1) AS idxs
WHERE all(i IN idxs WHERE NOT EXISTS {
    MATCH (parent)-[o:CONTAINS]->()
    WHERE parent = ns[i] AND o.version > rs[i].version
})
RETURN coalesce(sum(list_product(properties(rs, 'qty'))), 0) AS total_parts;
```

