MATCH (s:Set)
WHERE EXISTS {
  MATCH p = (s)-[:CONTAINS*1..20]->(m:Minifig {fig_num: 'fig-000506'})
  WHERE all(r IN rels(p) WHERE r.is_spare = false AND NOT EXISTS {
    MATCH (startNode(r))-[x:CONTAINS]->()
    WHERE x.version > r.version
  })
}
AND EXISTS {
  MATCH p = (s)-[:CONTAINS*1..20]->(part:Part {part_num: '98138'})
  WHERE all(r IN rels(p) WHERE r.is_spare = false AND NOT EXISTS {
    MATCH (startNode(r))-[x:CONTAINS]->()
    WHERE x.version > r.version
  })
}
RETURN count(DISTINCT s) AS set_count
